def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    strong_prev = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 70:
                    strong_prev.append(float(bid))

    if not alive:
        return float(min(budget, 18.0))

    units = int(supply / WATER_REQ)
    if units < 1:
        units = 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    second_prev = 0.0
    if len(prev_bids) >= 2:
        second_prev = sorted(prev_bids)[-2]

    danger = hp <= 3 or no_water_days >= 1
    critical = hp <= 2 or no_water_days >= 2

    if units == 1:
        if critical:
            bid = max(92.0, highest_prev + 2.0)
        elif danger:
            bid = max(78.0, second_prev + 2.0, highest_prev * 0.72)
        else:
            if highest_prev >= 120:
                bid = 58.0
            elif highest_prev >= 90:
                bid = 66.0
            else:
                bid = max(52.0, second_prev + 1.5)
    else:
        if critical:
            bid = max(72.0, second_prev + 1.5)
        elif danger:
            bid = max(54.0, min(78.0, second_prev + 1.5))
        else:
            if highest_prev >= 120:
                bid = 34.0
            elif highest_prev >= 90:
                bid = 42.0
            else:
                bid = 28.0

    live_count = len(alive)
    if live_count >= 3 and units == 1 and not danger:
        bid -= 4.0

    reserve_floor = 0.0
    if day_context['day'] <= 7:
        reserve_floor = 70.0
    if budget < reserve_floor + bid:
        bid = max(0.0, budget - reserve_floor)

    if critical and bid < 65.0:
        bid = min(budget, 65.0)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_current_bid = 0.0

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        # If no opponents, bid a small amount to get water for free
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    days_left = EPISODE_DAYS - day_context['day']

    # Critical state: must get water
    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        my_current_bid = DAILY_SALARY * 0.95 # Bid very high
        if highest_prev_bid > 0:
            my_current_bid = max(my_current_bid, highest_prev_bid + 5.0)
    # Low HP, need water but can be slightly less aggressive if opponents are weak
    elif my_status['hp'] <= 4:
        my_current_bid = DAILY_SALARY * 0.8
        if highest_prev_bid > 0:
            my_current_bid = max(my_current_bid, highest_prev_bid + 2.0)
    # Moderate to high HP
    else:
        if highest_prev_bid > DAILY_SALARY * 0.8:
            # Opponents are bidding very high, need to compete
            my_current_bid = highest_prev_bid + 1.0
        elif highest_prev_bid > DAILY_SALARY * 0.6:
            # Opponents are bidding moderately high
            my_current_bid = max(DAILY_SALARY * 0.7, highest_prev_bid + 1.0)
        else:
            # Opponents are bidding low or no recent high bids
            my_current_bid = DAILY_SALARY * 0.6
            if highest_prev_bid > 0:
                my_current_bid = max(my_current_bid, highest_prev_bid + 1.0)

    # Add a small buffer if budget allows and it's not too late in the game to outbid someone
    if my_status['budget'] > my_current_bid + 5.0 and days_left > 2:
        my_current_bid += 1.0

    # Ensure bid does not exceed budget and is not negative
    final_bid = min(my_status['budget'], my_current_bid)
    final_bid = max(0.0, final_bid)

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    # Gather yesterday's bids from alive opponents
    bids = []
    for opp in opponents_status.values():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bids.append(prev['bid'])

    # Determine base bid
    if bids:
        max_prev = max(bids)
        # Slightly beat the highest previous bid
        base = max_prev + 1.0
    else:
        base = DAILY_SALARY * 0.5

    # Adjust for urgency
    hp = my_status['hp']
    no_water = my_status['no_water_days']
    budget = my_status['budget']

    urgency = 0
    if no_water > 0:
        urgency = 2
    elif hp <= 3:
        urgency = 1

    if urgency == 2:
        # Must win water
        bid = min(budget, DAILY_SALARY * 0.95)
    elif urgency == 1:
        # High priority
        bid = min(budget, max(base, DAILY_SALARY * 0.7))
    else:
        # Conservative
        bid = min(budget, base, DAILY_SALARY * 0.75)

    # Ensure at least a minimal bid if desperate
    if hp <= 1:
        bid = min(budget, DAILY_SALARY * 0.98)

    # Cap by budget
    return max(1.0, min(budget, bid))
